-- 0018_saudi_project_practice
--
-- Saudi Project Practice - ELV / ICT / Fire / Security (SPT Pre-Sales,
-- 29 Sep 2026). 44 rules, plus a Retention & Power QuickRef and a source
-- register of 17 documents.
--
-- This document is indexed differently from the other four. They answer "what
-- is the rule for X?". This answers "what goes in THIS LOCATION?" -- perimeter
-- fence, gatehouse, hospital ward, mosque, battery room. That is the axis
-- pre-sales actually works in, and nothing in the first 137 rules covered it.
-- Hence two new columns, `applies_at_location` and `facility_context`, and a
-- location-indexed rule pack generated from them.
--
-- Confidence mapping:
--   Documented   -> 'local'  (an Aramco/HCIS/MOH client or authority standard,
--                             bounded to Saudi projects; jurisdiction 'SA')
--   Code-derived -> 'code'   (SBC 801 / NFPA basis)
--   Practice     -> 'spec'
--
-- 'Documented' is LOCAL rather than CODE because these are client and authority
-- standards, not international codes. That is not a demotion: on an Aramco or
-- HCIS site they bind harder than NFPA does. It does mean X-06 asks for a
-- citation before one becomes a quantity, which is right -- the citation is
-- what establishes the site is in scope of that standard.
--
-- source_verified is TRUE only for the three documents the register says were
-- read (SAES-O-205 2023, HCIS SEC-05 2017 pp.1-31, SAES-T-555 2012). Everything
-- else is a summary or keyword extract, and several are old public editions.
-- SBC 801 itself was never retrieved.
--
-- Idempotent.

alter table engineering_rules
  add column if not exists applies_at_location text,
  add column if not exists facility_context    text;

comment on column engineering_rules.applies_at_location is
  'Where this rule applies: perimeter fence line, gatehouse, hospital ward, '
  'mosque, battery room. Lets rules be retrieved by location rather than system.';
comment on column engineering_rules.facility_context is
  'Which kind of facility the location sits in, e.g. "Industrial, FSC Class 1-2" '
  'or "MOH / private hospital". Two rules can share a location and differ here.';

create index if not exists idx_engineering_rules_location
  on engineering_rules (organization_id, applies_at_location)
  where applies_at_location is not null;

create or replace function saudi_practice_seed()
returns table (
  system_code text, rule_code text, source_rule_id text, rule_name text,
  confidence public.rule_confidence, jurisdiction text, standard_reference text,
  priority integer, source_verified boolean, verification_note text,
  applies_at_location text, facility_context text,
  conditions jsonb, inputs jsonb, calculation jsonb, outputs jsonb, exceptions jsonb)
language sql immutable
set search_path = ''
as $fn$
select t.system_code, t.rule_code, t.source_rule_id, t.rule_name,
       t.confidence::public.rule_confidence, t.jurisdiction, t.standard_reference,
       t.priority, t.source_verified, t.verification_note,
       t.applies_at_location, t.facility_context,
       t.conditions::jsonb, t.inputs::jsonb, t.calculation::jsonb,
