create or replace function seed_saudi_practice(p_organization_id uuid)
returns integer
language plpgsql
set search_path = ''
as $fn$
declare v_loaded integer;
begin
  if not exists (select 1 from public.organizations o where o.id = p_organization_id) then
    raise exception 'organization % does not exist', p_organization_id
      using errcode = 'foreign_key_violation';
  end if;

  if exists (select 1 from public.saudi_practice_seed() r
             left join public.systems s on s.code = r.system_code
             where r.system_code is not null and s.id is null) then
    raise exception 'saudi_practice_seed references a system code with no row in systems';
  end if;

  insert into public.engineering_rules (
    organization_id, system_id, rule_code, name, jurisdiction, standard_reference,
    priority, confidence, source_document, source_rule_id, source_verified,
    verification_note, applies_at_location, facility_context)
  select p_organization_id, s.id, r.rule_code, r.rule_name, r.jurisdiction,
         r.standard_reference, r.priority, r.confidence,
         'standards-references/saudi-project-practice/',
         r.source_rule_id, r.source_verified, r.verification_note,
         r.applies_at_location, r.facility_context
  from public.saudi_practice_seed() r
  left join public.systems s on s.code = r.system_code
  on conflict do nothing;

  insert into public.rule_versions (
    rule_id, version, conditions, inputs, calculation, outputs, exceptions,
    approval_status)
  select er.id, 1, r.conditions, r.inputs, r.calculation, r.outputs,
         r.exceptions, 'draft'
  from public.saudi_practice_seed() r
  join public.engineering_rules er
    on er.organization_id = p_organization_id and er.rule_code = r.rule_code
  where not exists (select 1 from public.rule_versions rv where rv.rule_id = er.id);

  get diagnostics v_loaded = row_count;
  return v_loaded;
end $fn$;

create or replace function register_saudi_practice_relationships(p_organization_id uuid)
returns integer
language plpgsql
set search_path = ''
as $fn$
declare v_loaded integer;
begin
  insert into public.rule_relationships (
    organization_id, from_rule_id, to_rule_id, kind, note)
  select p_organization_id, a.id, b.id,
         t.kind::public.rule_relationship_kind, t.note
  from (values
('SPT-LP-07', 'KSA-CCTV-04', 'conflicts', 'LP-07 and the QuickRef set retention by CAMERA ROLE under Aramco/HCIS: gate surveillance 90 d, gate assessment (PTZ) 30 d, IDAS perimeter 60 d, VASS assessment 30 d. KSA-CCTV-04 records a 90-day statutory floor under the Law of the Use of Security Surveillance Cameras. The 30 d and 60 d figures sit BELOW that floor. If the premises fall under the camera law, the statutory minimum governs and a client standard cannot reduce it. Resolve per project: confirm whether the site is in scope of the law, and confirm the 90-day figure itself, which is still secondary-sourced.'),
('SPT-LP-07', 'SPT-CC-04', 'resolves', 'SPT-CC-04 said only ''retention per spec, commonly 30-90 days, verify''. LP-07 and the QuickRef give the actual Aramco/HCIS split by camera role with clause references, which is what a storage calculation needs.'),
('SPT-LP-26', 'ELV-A-02', 'agrees', 'SAES-T-624 gives OSP fibre bend as 10x unloaded / 20x under tension. OSP is interbuilding, which is exactly the case where ELV-A-02 (corrected from the supplied 568-B) says 20x is correct. This is independent corroboration that the ELV-A-02 reading is right and that SPT-SC-04''s flat 20x is the one that is wrong.'),
('SPT-LP-25', 'SPT-SC-09', 'agrees', 'Both put a telecom room per 1,000 m2. LP-25 adds Aramco room sizing (3.0x2.2 m to 500 m2; 3.0x3.4 m for 800-1,000 m2), 1-hour rated walls, no false ceiling, and RCDD-qualified design.'),
('SPT-LP-25', 'ELV-A-01', 'agrees', 'Both cap the horizontal run at 90 m.'),
('SPT-LP-16', 'SPT-UP-05', 'agrees', 'LP-16 cites the same IEC 62485-2 hydrogen dilution formula and names rule UP-05 directly.'),
('SPT-LP-19', 'SPT-UP-02', 'refines', 'Security systems must be on UPS backed by an emergency generator. The autonomy figure sits in SEC-07 / SAES-O-207, which could NOT be retrieved - so the runtime input to UP-02 is unknown for HCIS security systems.'),
('SPT-LP-30', 'SPT-UP-01', 'refines', 'Hospital critical care: generator >=3 h and loads designed at 120%. UP-01 sizes to 80% of rating; the MOH 120% load factor is a different and stricter basis for the same decision.'),
('SPT-LP-31', 'SPT-UP-02', 'refines', 'Gives a concrete runtime for hospital light-current systems: >=30 min.'),
('SPT-LP-44', 'SPT-FA-04', 'agrees', 'Heat detectors where smoke would false-alarm, spacing per listing x height factor - the same height-factor ladder FA-04 carries.'),
('SPT-LP-40', 'SPT-FA-14', 'agrees', 'Hotel sleeping rooms: 520 Hz low-frequency tone, 75 dBA at pillow or 15 dB above ambient.'),
('SPT-LP-28', 'SPT-AC-03', 'agrees', 'Hospital external fire exits release on alarm; FACP interfaces to lifts, AC, BMS, PA and door holders - the same cause-and-effect interface AC-03 and ELV-X-03 require.'),
('SPT-LP-33', 'SPT-AC-01', 'agrees', 'Electrically locked doors on hospital escape routes interlocked with the fire alarm.'),
('SPT-LP-23', 'SPT-CC-10', 'refines', 'CC-10 required an enclosure rated to site ambient without giving one. LP-23 supplies the KSA design maxima: indoor AC 35 C, outdoor sheltered 70 C, unsheltered 80 C, plus a +15 C self-heating rule, dust to 500 mg/m3, and a definition of coastal (1 km Gulf / 3 km Red Sea).'),
('SPT-LP-22', 'SPT-CC-10', 'refines', 'Hazardous areas need Ex-certified cameras and housings per the area classification drawing.'),
('SPT-LP-43', 'SPT-CC-08', 'agrees', 'PoE to 100 m, fibre beyond - the same limit CC-08 sets.'),
('SPT-LP-24', 'SPT-NW-04', 'refines', 'Remote leased links: camera traffic <=10% of the link with >=20% free before adding cameras. Stricter and more specific than the general oversubscription guidance.'),
('SPT-LP-21', 'SPT-NW-07', 'agrees', 'Plant-ops CCTV on a separate VLAN with control traffic prioritised - the segmentation NW-07 requires, applied to a process network.'),
('SPT-LP-18', 'SPT-NW-03', 'refines', 'Security core spare capacity is specified as 20% CPU/RAM, 20% ports, 20% bandwidth and 50% disk, with >=99.95% availability per component - firmer than the general 20-25% port spare.'),
('SPT-LP-20', 'SPT-CC-01', 'refines', 'Fixed cameras for surveillance and analytics, PTZ for assessment, with optical 1080p@30 and thermal LWIR >=320x240@30 - the equipment side of the DORI decision.'),
('SPT-LP-03', 'SPT-CC-01', 'refines', 'Optical cameras need light: area average 5 lux, switch-on at 1.6x design lux or 15 lux. A pixel-density target is not achievable below the lighting level.')  ) as t(from_code, to_code, kind, note)
  join public.engineering_rules a
    on a.organization_id = p_organization_id and a.rule_code = t.from_code
  join public.engineering_rules b
    on b.organization_id = p_organization_id and b.rule_code = t.to_code
  on conflict (from_rule_id, to_rule_id) do nothing;

  get diagnostics v_loaded = row_count;
  return v_loaded;
end $fn$;

comment on function register_saudi_practice_relationships(uuid) is
  'The headline one is LP-07 vs KSA-CCTV-04: Aramco/HCIS set CCTV retention by '
  'camera role (30 d assessment, 60 d IDAS perimeter, 90 d gate/VASS), and the '
  '30 d and 60 d figures sit BELOW the 90-day statutory floor in the Law of the '
  'Use of Security Surveillance Cameras. A client standard cannot reduce a '
  'statutory minimum, so this must be resolved per project.';

do $$
declare o record; v_conf integer;
begin
  for o in select id, name from organizations loop
    perform seed_saudi_practice(o.id);
    perform register_saudi_practice_relationships(o.id);
    select count(*) into v_conf from rule_relationships
     where organization_id = o.id and kind in ('conflicts','supersedes')
       and resolved_at is null;
    raise notice 'Saudi project practice loaded for % (%): % unresolved conflict(s)',
      o.name, o.id, v_conf;
  end loop;
end $$;
